"""Every committed L0 member is regenerated byte for byte or pinned as an authored document."""
from pathlib import Path
import hashlib
import re
import sys
import tempfile
import unittest

REPO = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO))
from tools import gen_l0_pack

# Members without a generator step; docs/architecture/data-formats/l0-provenance.md records the origin of each.
HAND_AUTHORED = {
    "gui/game_won.gui",
    "gui/layouts.json",
    "pack.json",
    "scenarios/campaign.json",
}


# Frozen authored documents are checked too, rather than merely exempted from generation.
HAND_AUTHORED_SHA256 = {
    'pack.json': 'e47212c14e5d53f137053c08122e22bb03f810d42ad3c1b4b986580d06c7c228',
    'gui/layouts.json': '593adb7865de2ddef6928247a5e8a468631b226f6f76692de8c9b1eba8c6f7e6',
    'gui/game_won.gui': '650c71c83afc37f439e8e99e67159acefa3fb24a75ce5035aff54dca05d9521b',
    'scenarios/campaign.json': 'fda158b129e1f3f835c07cb59e56c43d71c6ba8402a3ace0e19c24fe08269128',
}


def members(root: Path) -> set[str]:
    return {p.relative_to(root).as_posix() for p in root.rglob("*") if p.is_file()}


class L0PackReproducible(unittest.TestCase):
    def test_startup_picture_references(self):
        pack = REPO / "data/packs/l0"
        for layout in ("main_menu", "intro"):
            text = (pack / "gui" / f"{layout}.gui").read_text(encoding="utf-8")
            pictures = re.findall(r"TGA\([^\n]*, ([A-Za-z0-9_]+)\.tga\)", text)
            self.assertTrue(pictures, layout)
            self.assertEqual(text.count("TGA("), len(pictures), "screen references require logical .tga suffix")
            for name in pictures:
                self.assertTrue(name.startswith("l0_"), name)
                self.assertTrue((pack / "images/screens" / f"{name}.png").is_file(), name)

    def test_generator_reproduces_members(self):
        pack = REPO / "data/packs/l0"
        with tempfile.TemporaryDirectory() as directory:
            out = Path(directory)
            argv = sys.argv
            sys.argv = ["gen_l0_pack.py", "--out", str(out)]
            try:
                gen_l0_pack.main()
            finally:
                sys.argv = argv
            generated = members(out)
            committed = members(pack)
            self.assertEqual(generated - committed, set(), "generated but not committed")
            self.assertEqual(committed - generated, HAND_AUTHORED, "undocumented hand-authored members")
            for name, digest in HAND_AUTHORED_SHA256.items():
                with self.subTest(member=name):
                    self.assertEqual(hashlib.sha256((pack / name).read_bytes()).hexdigest(), digest)
            self.assertEqual(set(HAND_AUTHORED_SHA256), HAND_AUTHORED)
            for name in sorted(generated):
                with self.subTest(member=name):
                    self.assertEqual((out / name).read_bytes(), (pack / name).read_bytes())


if __name__ == "__main__":
    unittest.main()
